from pathlib import Path
from datetime import date

from date_window import previous_month_window
from mock_api import TRACE, search_sales
from nlp_extractors import infer_region_phrase, infer_sort_clause
from request_assembly import build_api_payload, build_internal_request
from report_formatter import summarize_rows
from sales_contract import INTERNAL_REQUEST_SCHEMA


def extract_params(query):
    return {
        "region": infer_region_phrase(query),
        "sort_phrase": infer_sort_clause(query),
    }


def validate_params(params):
    """Return structured validation errors without making an API request."""
    errors = []
    schema = INTERNAL_REQUEST_SCHEMA

    for field_name in schema.get("required", ()):
        if field_name not in params or params[field_name] is None:
            errors.append({
                "field": field_name,
                "error": "missing",
                "message": f"Required field '{field_name}' is missing",
            })
        elif params[field_name] == "":
            errors.append({
                "field": field_name,
                "error": "empty",
                "message": f"Required field '{field_name}' is empty",
            })

    for field_name, expected_type in schema.get("types", {}).items():
        if field_name in params and params[field_name] is not None:
            if not isinstance(params[field_name], expected_type):
                errors.append({
                    "field": field_name,
                    "error": "wrong_type",
                    "message": (
                        f"'{field_name}' must be {expected_type.__name__}, "
                        f"got {type(params[field_name]).__name__}"
                    ),
                })

    for field_name, allowed in schema.get("enums", {}).items():
        if field_name in params and isinstance(params[field_name], str):
            if params[field_name] not in allowed:
                errors.append({
                    "field": field_name,
                    "error": "invalid_option",
                    "message": f"'{field_name}' must be one of {list(allowed)}",
                })

    parsed_dates = {}
    for field_name in schema.get("formats", {}):
        value = params.get(field_name)
        if isinstance(value, str):
            try:
                parsed_dates[field_name] = date.fromisoformat(value)
            except ValueError:
                errors.append({
                    "field": field_name,
                    "error": "invalid_format",
                    "message": f"'{field_name}' must be an ISO date (YYYY-MM-DD)",
                })

    if (
        "start_date" in parsed_dates
        and "end_date" in parsed_dates
        and parsed_dates["start_date"] > parsed_dates["end_date"]
    ):
        errors.append({
            "field": "date_range",
            "error": "invalid_range",
            "message": "'start_date' must not be later than 'end_date'",
        })
    return errors


def normalize_params(params):
    return build_internal_request(params)


def run_pipeline(query_path):
    TRACE.clear()
    query = Path(query_path).read_text(encoding="utf-8").strip()
    params = extract_params(query)
    internal_request = normalize_params(params)
    start, end = previous_month_window()
    internal_request["start_date"] = start
    internal_request["end_date"] = end
    errors = validate_params(internal_request)
    if errors:
        return {"count": 0, "total_amount": 0, "average_amount": 0, "rows": [], "errors": errors}
    api_payload = build_api_payload(internal_request)
    rows = search_sales(api_payload)
    return summarize_rows(rows)

