def summarize_rows(rows):
    total = sum(item["amount"] for item in rows)
    average = total / len(rows) if rows else 0
    rows = sorted(rows, key=lambda item: item["amount"], reverse=True)
    return {
        "count": len(rows),
        "total_amount": total,
        "average_amount": average,
        "rows": rows,
    }

